SELECT sr.sr_ticket_number, cd.cd_gender, CASE WHEN cd.cd_education_status = 'College             ' THEN 'HighEdu' WHEN cd.cd_education_status = 'Secondary           ' THEN 'MidEdu' ELSE 'LowEdu' END AS education_category, (sr.sr_return_amt + sr.sr_return_tax) * 10 AS total_return_with_factor, sr.sr_return_quantity * sr.sr_return_amt AS quantity_times_amount, CASE WHEN sr.sr_return_amt_inc_tax > 251.97 THEN 'High' ELSE 'Low' END AS return_level, sr.sr_return_amt_inc_tax - sr.sr_return_tax AS net_amount_excluding_tax FROM store_returns AS sr JOIN customer_demographics AS cd ON sr.sr_cdemo_sk = cd.cd_demo_sk WHERE sr.sr_returned_date_sk = 2451053 AND cd.cd_gender = 'M'
